/*
 * Continuous adaptation of d17e.dev's Genuary 2025 #16
 * -> https://www.instagram.com/p/DFLJqFsSTsI/
 *
 * Now using mixbox blending!
 *
 * Use the mouse to control the positions of the control points.
*/

#define TIME (iTime * 0.25)
#define TAU 6.2831853
#define N 4

const float rs[N] = float[] (1., 1.3, 0.9, 1.2);
const float rScale = 2.;

const vec3 cols[N] = vec3[] (
    vec3(1.000,0.251,0.000),
    vec3(0.882,1.000,0.000),
    vec3(1.000,0.541,0.678),
    vec3(0.859,0.976,1.000)
);


vec2 getPos(int index) {
	vec2 pos;
    vec2 m = (iMouse.x < 20. && iMouse .y < 20.) ? /// not mouse in corner
		vec2(0.73, 0.32) * iResolution.xy : 
		iMouse.xy;
	m = (m - iResolution.xy/2.) / iResolution.y * 2.;

	if     (index == 0) pos = vec2(-0.35, -0.7);	
	else if(index == 1) pos = m.xy;
	else if(index == 2) pos = m.xy * vec2(0.26, -0.8);
	else if(index == 3) pos = m.xy * vec2(-0.6, -0.2);

	// correct aspect ratio
    pos.x *= iResolution.x / iResolution.y;

    float th = float(index + 10) * 1.618 * TAU + TIME * (1.618 + float(index + 1));
    vec2 circ = vec2(cos(th), sin(th)) * 1.;

	return pos + circ;
}

float getCloseness(float dst, float ri) {
    return max(0.0001, 1. - dst / ri);
}

vec4 compCol(in vec2 pos) {
    float dstMetrics[N];
    float totDstMetric = 0.;
	for (int i = 0; i < N; i++) {
        float ri = rs[i] * rScale;
        float dstMetric = getCloseness(distance(pos, getPos(i)), ri);
        dstMetrics[i] = dstMetric;
        totDstMetric += dstMetric;
	}

	mixbox_latent latentCol = mixbox_latent(0.);
	for (int i = 0; i < N; i++) {
        mixbox_latent latentColi = mixbox_rgb_to_latent(cols[i]);
        //mixbox_latent latentColi = latentCols[i];
        latentCol += latentColi * dstMetrics[i] / totDstMetric;
    }
    vec3 col = mixbox_latent_to_rgb(latentCol);
	return vec4(col, 1.);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
	vec2 pos = (fragCoord.xy - iResolution.xy/2.) / iResolution.y * 2.;
    if (iMouse.z > 0.)
        pos *= 4.;
	fragColor = compCol(pos);
}

struct Pigment
